/**
 * 🔴 THE N-TERMINAL FORM IS THE INTERNAL ONE. Checked for all 21 components:
 * their atom sets are equal, so only two forms are stored. The C-terminal form
 * is the internal one plus an OXT, for every type without exception.
 */
export function conformerFor(code, isCTerminal) {
  const entry = REFERENCE_CONFORMERS[code] ?? REFERENCE_CONFORMERS.X;
  return isCTerminal ? entry.cTerminal : entry.internal;
}

/** AF3's aatype for a one-letter code; anything unknown is UNK. */
export function aatypeFor(code) {
  return (REFERENCE_CONFORMERS[code] ?? REFERENCE_CONFORMERS.X).aatype;
}
